python3 -c "
import math

for n in range(1, 10001):
    for p in range(0, 101):
        # Exact integer rank if integer
        if (p * n) % 100 == 0:
            expected_rank = (p * n) // 100
        else:
            expected_rank = (p * n) // 100 + 1
        if expected_rank == 0:
            expected_rank = 1

        float_rank = math.ceil(p * n / 100)
        if float_rank == 0:
            float_rank = 1

        if expected_rank != float_rank:
            print(f'Mismatch: n={n}, p={p}, expected={expected_rank}, float={float_rank}')
            break
print('Finished 10000 check')
"

